settings.custom_css:
@media screen and (max-width:480px){
    .mob-flex{
        display: flex;
        flex-direction: column;
    }
}

.trust-box figure.elementor-image-box-img {
    background: #0C54A3;
    padding: 13px;
    border-radius: 50px;
    margin-top: -30px !important;
    transition: all ease 300ms;
}

.trust-box figure.elementor-image-box-img img {
    width: 41px;
    filter: brightness(1) invert(1);
}

.trust-box:hover figure.elementor-image-box-img{
       background: var( --e-global-color-secondary ) !important;
}
